from pathlib import Path
import hashlib,json
R=Path(__file__).parent
C=json.loads((R/'input-contract.json').read_text(encoding='utf-8-sig'))
def j(p,x): (R/p).write_text(json.dumps(x,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
def h(p):return hashlib.sha256((R/p).read_bytes()).hexdigest()
order=[f'lesson-{i:02}' for i in range(1,8)]
for i,k in enumerate(order,1):
    s=(R/(k+'.md')).read_text(encoding='utf-8')
    for end in ['E1','W1','P1','D1']: assert f'C24.{i:02}-{end}' in s
    for label in ['Essential question:','Goals','Prerequisite bridge:','Next dependency:','Answers:']:assert label in s
assembled='# Moving Reference Frames and Laboratory Motion\n\nStudent course • seven lessons • eleven core periods\n\nSupporting [glossary](terminology.md), [capstone and full answers](capstone.md), [teacher guide](teacher-guide.md), and [source ledger](sources.md).\n\n'
for k in order:assembled+=f'<!-- BEGIN: {k} -->\n'+(R/(k+'.md')).read_text(encoding='utf-8').rstrip('\n')+f'\n<!-- END: {k} -->\n\n'
(R/'course.md').write_text(assembled,encoding='utf-8')
counts=dict(critical=0,major=0,minor=0)
finding=dict(id='AUD-24-001',level='local',category='assumption clarity',file='lesson-01.md',section='C24.01-W1',severity='minor',defect='Worked velocity paragraph explicitly fixed the origin but did not restate fixed R, though preceding explanation gave that condition.',correction='Explicitly state both R and o constant throughout the velocity interval.',verification='Independent auditor identified wording; manager inspected corrected sentence and retained all recomputed outputs.',disposition='corrected',affected_checkpoints=['lesson-01','assembly'])
checks=[
dict(level='local',scope='lessons 01–07',method='Manager and independent auditor read all lesson anchors, prerequisite bridges, definitions, notation, units, diagnostic questions/answers and evidence boxes.',result='No critical/major defects; one minor fixed-origin/rotation clarification repaired.'),
dict(level='cumulative',scope='boundaries after lessons 02,04,07',method='Trace component transform to triad, triad to chain, derivative bridge to moving frames, fixed/carried distinction to display and final contract.',result='No prerequisite inversion; all seven concepts introduced, practiced and assessed. Radius r and residual r have explicit separate scopes.'),
dict(level='final',scope='capstone and teacher materials',method='Independent auditor reread all seven tasks and keys against approved backward map and prior answered practice; recomputed all answers and 28-point total.',result='Zero critical/major/minor findings; 11 core plus 3 capstone periods consistent.'),
dict(level='final',scope='source fidelity',method='Manager retrieved full bounded T10/T40/T45/T50 bytes with matching hashes; local physical authority hash and vector inspected. Independent auditor separately checked physical authority and norm.',result='Exact numerical/source boundaries retained. Remote report of formal result not promoted to fresh compilation. Missing epoch and generation freshness disclosed.'),
dict(level='final',scope='numerical and dimensional correctness',method='verify_examples.py: 28 standard-library checks, including independent finite-difference derivative check, inverse reconstruction, signed sums, spherical norm and physical source norm.',result='All passed in tf_gpu_env; no source arrays copied.'),
dict(level='final',scope='coverage, fidelity, dependency, terminology, evidence, audience, assessment, recovery, assembly, minimality',method='Read final lessons/support; checked named E/W/P/D anchors and seven capstone links, concise prerequisite bridges, explicit limits, and identical assembly marker extraction.',result='All required topical operations present; no new instruction in assembly. Markdown only, no paginated rendering required. Deterministic validator executed separately after hashes were finalized.')]
j('audit_report.json',dict(schema_version='1.0',status='passed',findings=[finding],unresolved_counts=counts,checks=checks,independent_audit='course_audit subagent completed separate lesson and capstone/support reads; no compiler execution claimed'))
spec=[('course-map','course-map','course-map.md',[]),*[(k,'lesson',k+'.md',['course-map'] if i==0 else [order[i-1]]) for i,k in enumerate(order)],('terminology','terminology','terminology.md',order),('teacher-guide','teacher-guide','teacher-guide.md',order),('capstone','capstone','capstone.md',order),('sources','supplement','sources.md',[]),('verification-script','supplement','verify_examples.py',order),('verification','supplement','worked-example-verification.json',['verification-script']),('assembly','assembly','course.md',order),('audit','audit','audit_report.json',['capstone','verification','assembly'])]
cp=[dict(id=i,kind=k,path=p,dependencies=d,status='passed',sha256=h(p),summary=('Verified '+k+' artifact; see audit_report.json for actual review scope.')) for i,k,p,d in spec]
outputs=[x['path'] for x in cp]+['completion_report.json']
assumptions=C['assumptions']+['Synthetic fixed-frame and rotating-frame exercises; no real propagation with an unspecified source epoch.','No fresh Agda compilation or live observational replay; exact source text retained as source-reported authority.','Optional Lesson 4 recovery period if derivative bridge needs additional practice.']
m=dict(schema_version='1.0',topic=C['topic'],audience=C['audience'],assumptions=assumptions,ordered_deliverables=outputs,checkpoints=cp,dependencies={x['id']:x['dependencies'] for x in cp},course_order=order,assembly=dict(path='course.md',section_ids=order),audit_counts=counts,blockers=[],next_action='none',course_output_directory=str(R),input_contract_sha256=h('input-contract.json'))
j('manifest.json',m)
j('completion_report.json',dict(status='complete',topic=m['topic'],audience=m['audience'],assumptions=assumptions,outputs=outputs,audit_counts=counts,hashes={p:h(p) for p in outputs if p!='completion_report.json'}|{'manifest.json':h('manifest.json')},lesson_count=7,core_periods=11,capstone_periods=3,source_gaps=['Physical source vector epoch unspecified; no real propagation assigned.','Capabilities response omitted requested generation/manifest pair; retrieved object hashes match.','Underlying formal contracts not independently compiled; formal claims remain source-reported.'],validator_command='conda run -n tf_gpu_env python Z:/Kfield-doc-training/.work/validate_project_course.py '+str(R)+' --json',validator_result_file='validator-result.json'))
print('Assembly, reviewed checkpoints and recovery hashes finalized.')
